export type GetPostResponse = GetPostResponses[keyof GetPostResponses];

export type UpdatePostData = {
    body?: {
        /**
         * Textual content of the post. User mentions can be added by inserting an @ followed by the ID or public identifier of the user (example: @JohnDoe).
         */
        text?: string;
        /**
         * The comment control level for the new post (if supported by the provider).
         * - `anyone` is visible to anyone.
         * - `relations_only` is visible only to the user's relations.
         * - `no_one` is visible to no one.
         */
        can_comment?: 'anyone' | 'relations_only' | 'no_one';
    };
    path: {
        /**
         * The ID of the Post to update.<br>Use IDs from *Get a Post*, *Create a Post* or *List all User's Posts* methods responses only. Some providers may allow native Post IDs, please refer to Posts integration guides.
         */
        post_id: string;
        /**
         * ID of the Account (acc_xxx) to call the method on behalf of.
         */
        account_id: string;
    };
    query?: never;
    url: '/v2/{account_id}/posts/{post_id}';
};

