export type StartAuthIntentResponses = {
    /**
     * Default Response
     */
    200: {
        object: 'AuthenticationCheckpoint';
        /**
         * The details of the checkpoint that user needs to solve.
         */
        checkpoint: {
            type: 'OTP';
        } | {
            type: 'IN_APP_VALIDATION';
        } | {
            type: 'PHONE_REGISTER';
        } | {
            type: '2FA';
            /**
             * The platform of the 2FA.
             * - `SMS` means the code was sent in a SMS.
             * - `APP` means the user must enter the code generated by the Authenticator App used to setup 2FA.
             * - `WHATSAPP` means the code was sent via WhatsApp.
             */
            platform: 'SMS' | 'APP' | 'WHATSAPP';
        } | {
            type: 'CAPTCHA';
            /**
             * The public key of the CAPTCHA. This is used to verify the CAPTCHA.
             */
            public_key: string | null;
            /**
             * The data of the CAPTCHA. This is used to verify the CAPTCHA.
             */
            data: string | null;
        } | {
            type: 'OTP_OR_IN_APP_VALIDATION';
        };
        /**
         * The ID of the auth intent. This should be used in Solve Checkpoint.
         */
        intent_id: string;
    } | {
        object: 'AuthenticationQrCode';
        /**
         * The QR Code to scan.
         */
        qrcode: string;
        /**
         * The ID of the auth intent. This should be used to listen for the QR Code scan with Solve Checkpoint.
         */
        intent_id: string;
    } | {
        object: 'OauthUrl';
        /**
         * The URL to redirect to start the oauth flow of the provider.
         */
        url: string;
    } | {
        object: 'Account';
        /**
         * The ID of the user that owns the account for the provider.
         */
        user_id: string;
        /**
         * The name of the account. This is usually the display name or public identifier (phone number, email address, etc.) of the user that owns the account.
         */
        name?: string;
        /**
         * The date and time the account was linked with Unipile.
         */
        created_at: string;
        /**
         * ID of the account.
         */
        id: string;
        /**
         * ID of the parent application.
         */
        application_id: string;
        /**
         * The current status of the account.
         * - `running` is Operational.
         * - `error` is Service Interuption.
         * - `disconnected` is Require Authentication..
         * - `paused` is Paused.
         * Learn more about [Status & Lifecycle](https://developer.unipile.com/v2.0/docs/status-lifecycle).
         */
        status: 'running' | 'errored' | 'disconnected' | 'paused';
        /**
         * The provider's of the Account.
         * - `mock` is mock.
         * - `whatsapp` is WhatsApp.
         * - `linkedin` is LinkedIn.
         * - `instagram` is Instagram.
         * - `google` is Google.
         * - `outlook` is Outlook.
         * - `telegram` is Telegram.
         * - `imap` is IMAP.
         */
        provider: 'mock' | 'whatsapp' | 'linkedin' | 'google' | 'outlook' | 'imap' | 'telegram' | 'instagram';
        /**
         * If the provider is OAuth, this is the scope of comma-separated permissions granted to the account.
         */
        oauth_scope?: string;
        metadata: {
            /**
             * The chosen country for the automatic proxy selection.
             */
            auto_proxy_country?: string;
            /**
             * The ID of the account in the v1 if the account is migrated from v1.
             */
            v1_account_id?: string;
            /**
             * The status of the connection to a product, if the account is connected to multiple products.
             */
            products_connection_status?: {
                [key: string]: 'running' | 'disconnected' | 'errored';
            };
            /**
             * Custom data of the account. This is where you can store custom data using "Update an account" method.
             */
            custom_data?: {
                [key: string]: string;
            };
        };
        /**
         * Sync details if the account has initial sync enabled.
         */
        initial_sync?: {
            /**
             * The state of an account’s initial provider sync.
             * - `pending`sync hasn’t started yet.
             * - `running` sync is currently in progress.
             * - `failed` sync could not be completed due to an error.
             * - `completed` sync finished successfully.
             * .
             */
            status: 'pending' | 'running' | 'failed' | 'completed';
            /**
             * The date and time the initial sync started.
             */
            started_at?: string;
        };
        /**
         * The proxy used for the account.
         */
        proxy?: {
            /**
             * The country of the proxy. If null, the proxy has no defined country.
             */
            country: string | null;
            /**
             * Whether the proxy was set automatically by Unipile.
             */
            auto_proxy: boolean;
            /**
             * The host of the custom proxy.
             */
            host?: string;
            /**
             * The port of the custom proxy.
             */
            port?: number;
            /**
             * The username used to authenticate to the custom proxy.
             */
            username?: string;
            /**
             * The protocol of the custom proxy.
             */
            protocol?: string;
        };
    };
};

export type StartAuthIntentResponse = StartAuthIntentResponses[keyof StartAuthIntentResponses];

